1	'use strict';
2	// Token Domain: CommandRewriter service.
3	// Contract: read PreToolUse JSON from stdin, output modified_input if rewrite needed.
4	// Empty stdout = passthrough. Fail-safe: any error → process.exit(0) → passthrough.
5	
6	const EXEMPT = new Set([
7	  'echo','printf','pwd','whoami','cd','pushd','popd','source','.','export',
8	  'unset','set','env','true','false','exit','return','break','continue',
9	  '[','test','if','while','for','do','done','fi','then','else','elif',
10	  'case','esac','function','read','wait','sleep','kill','exec','eval',
11	  'mkdir','rmdir','rm','mv','cp','touch','chmod','chown','type','which','where',
12	]);
13	
14	function processSegment(seg) {
15	  const trimmed = seg.trim();
16	  if (!trimmed) return seg;
17	  if (trimmed.startsWith('RTK_DISABLED=1')) return seg;           // bypass env
18	  let prefix = '', rest = trimmed;
19	  const m = rest.match(/^([A-Z_][A-Z0-9_]*=[^\s]*\s+)*/i);
20	  if (m && m[0]) { prefix = m[0]; rest = rest.slice(prefix.length).trim(); }
21	  if (!rest) return seg;
22	  if (rest.startsWith('rtk ') || rest === 'rtk') return seg;      // already prefixed
23	  const cmdWord = rest.split(/\s+/)[0].replace(/^[!-]+/, '');
24	  if (EXEMPT.has(cmdWord) || '({)}'.includes(cmdWord)) return seg; // shell builtin
25	  const leading  = seg.match(/^\s*/)[0];
26	  const trailing = seg.match(/\s*$/)[0];
27	  return leading + prefix + 'rtk ' + rest + trailing;
28	}
29	
30	function splitByLogicalOps(cmd) {
31	  const tokens = []; let cur = '', i = 0;
32	  while (i < cmd.length) {
33	    const ch = cmd[i];
34	    if (ch === "'") {
35	      let j = i + 1;
36	      while (j < cmd.length && cmd[j] !== "'") j++;
37	      cur += cmd.slice(i, j + 1); i = j + 1; continue;
38	    }
39	    if (ch === '"') {
40	      let j = i + 1;
41	      while (j < cmd.length && cmd[j] !== '"') { if (cmd[j] === '\\') j++; j++; }
42	      cur += cmd.slice(i, j + 1); i = j + 1; continue;
43	    }
44	    if (ch === '`') {
45	      let j = i + 1;
46	      while (j < cmd.length && cmd[j] !== '`') j++;
47	      cur += cmd.slice(i, j + 1); i = j + 1; continue;
48	    }
49	    if (ch === '$' && cmd[i + 1] === '(') {
50	      let d = 0, j = i;
51	      while (j < cmd.length) {
52	        if (cmd[j] === '(') d++;
53	        else if (cmd[j] === ')') { d--; if (!d) { j++; break; } }
54	        j++;
55	      }
56	      cur += cmd.slice(i, j); i = j; continue;
57	    }
58	    if (ch === '&' && cmd[i + 1] === '&') { tokens.push({ text: cur, sep: '&&' }); cur = ''; i += 2; continue; }
59	    if (ch === '|' && cmd[i + 1] === '|') { tokens.push({ text: cur, sep: '||' }); cur = ''; i += 2; continue; }
60	    if (ch === '|') { cur += ch; i++; continue; }   // pipe: NOT split (continuation)
61	    if (ch === ';') { tokens.push({ text: cur, sep: ';'  }); cur = ''; i++;    continue; }
62	    cur += ch; i++;
63	  }
64	  tokens.push({ text: cur, sep: '' });
65	  return tokens;
66	}
67	
68	function rewriteCommand(cmd) {
69	  const tokens = splitByLogicalOps(cmd);
70	  let changed = false;
71	  const out = tokens.map(({ text, sep }) => {
72	    const n = processSegment(text);
73	    if (n !== text) changed = true;
74	    return { text: n, sep };
75	  });
76	  return changed ? out.map(({ text, sep }) => text + sep).join('') : null;
77	}
78	
79	let input = '';
80	process.stdin.setEncoding('utf8');
81	process.stdin.on('data', c => { input += c; });
82	process.stdin.on('end', () => {
83	  try {
84	    const p = JSON.parse(input);
85	    if (p.tool_name !== 'Bash') process.exit(0);
86	    const cmd = (p.tool_input && p.tool_input.command) || '';
87	    if (!cmd) process.exit(0);
88	    const rw = rewriteCommand(cmd);
89	    if (rw !== null) process.stdout.write(JSON.stringify({ modified_input: { command: rw } }));
90	    process.exit(0);
91	  } catch (_) { process.exit(0); }
92	});
