1	# Stop hook: append rtk session stats to ~/.claude/reports/token-usage.md.
2	# Idempotent per-day heading. One row per session.
3	
4	$ErrorActionPreference = 'SilentlyContinue'
5	
6	$ClaudeRoot = if ($env:CLAUDE_CONFIG_DIR) { $env:CLAUDE_CONFIG_DIR } else { Join-Path $env:USERPROFILE '.claude' }
7	$reportsDir = Join-Path $ClaudeRoot 'reports'
8	$file       = Join-Path $reportsDir 'token-usage.md'
9	if (-not (Test-Path $reportsDir)) { New-Item -ItemType Directory -Force -Path $reportsDir | Out-Null }
10	
11	# Pull rtk gain session JSON (best-effort; rtk may be missing or schema may differ)
12	$json = $null
13	try {
14	    $raw = & rtk gain --session --json 2>$null
15	    if ($raw) { $json = ($raw -join "`n") | ConvertFrom-Json }
16	} catch {}
17	
18	$today     = Get-Date -Format 'yyyy-MM-dd'
19	$timestamp = Get-Date -Format 'HH:mm'
20	
21	$saved = 'n/a'
22	$ratio = 'n/a'
23	$count = 'n/a'
24	if ($json) {
25	    $sess = $null
26	    if     ($json.session)  { $sess = $json.session }
27	    elseif ($json.PSObject.Properties['session_total']) { $sess = $json.session_total }
28	    else { $sess = $json }
29	    if ($sess.total_saved)  { $saved = $sess.total_saved }
30	    if ($sess.savings_ratio) { $ratio = "{0:N1}%" -f ([double]$sess.savings_ratio * 100) }
31	    if ($sess.commands)     { $count = $sess.commands }
32	}
33	
34	$row = "| $timestamp | $count | $saved | $ratio |"
35	
36	if (-not (Test-Path $file)) {
37	    $header = @(
38	        '# Token Usage Report',
39	        '',
40	        '_Auto-generated by Stop hook (`token-report.ps1`). Append-only. One row per session._',
41	        ''
42	    ) -join "`n"
43	    Set-Content -Path $file -Value $header -Encoding UTF8
44	}
45	
46	$content = Get-Content $file -Raw -Encoding UTF8
47	$dayHeader = "## $today"
48	if (-not $content -or ($content -notmatch [regex]::Escape($dayHeader))) {
49	    $tableHeader = "`n$dayHeader`n`n| Time | Commands | Tokens saved (rtk) | Saved ratio |`n|---|---|---|---|"
50	    Add-Content -Path $file -Value $tableHeader -Encoding UTF8
51	}
52	Add-Content -Path $file -Value $row -Encoding UTF8
53	
54	# Audit Domain: missed savings projection — hook compliance audit.
55	# After Token Domain hook is active, this output should approach zero.
56	try {
57	    $disc = & rtk discover --all 2>$null
58	    if ($disc) {
59	        Add-Content -Path $file -Value (
60	            "`n### rtk discover (missed savings)`n``````n" +
61	            ($disc -join "`n") + "`n``````n"
62	        ) -Encoding UTF8
63	    }
64	} catch {}
65	
66	exit 0
